// SPDX-License-Identifier: GPL-3.0
// Contour material: moving reflection v2.
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec2 uPointer;
uniform float uPower;
uniform float uFoilAspect;
uniform float uContourPower;
uniform float uFoilStrength;
uniform sampler2D uCard;
uniform sampler2D uFoil;
uniform sampler2D uContour;
uniform sampler2D uBloom;
out vec4 fragColor;
#include "foil_material.glsl"
#include "contour_material.glsl"
void main() {
  vec2 uv = FlutterFragCoord().xy / uSize;
  vec4 source = texture(uCard, uv);
  vec3 card = source.rgb / max(source.a, 0.001);
  vec3 result = foilMaterial(uv, card, uPower * uFoilStrength);
  result = contourMaterial(uv, card, result);
  fragColor = vec4(result*source.a, source.a);
}

// SPDX-License-Identifier: GPL-3.0
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec2 uPointer;
uniform float uPower;
uniform float uFoilAspect;
uniform sampler2D uCard;
uniform sampler2D uFoil;
out vec4 fragColor;
#include "foil_material.glsl"
void main() {
  vec2 uv = FlutterFragCoord().xy / uSize;
  vec4 source = texture(uCard, uv);
  vec3 card = source.rgb / max(source.a, 0.001);
  vec3 result = foilMaterial(uv, card, uPower);
  fragColor = vec4(result*source.a, source.a);
}

// SPDX-License-Identifier: GPL-3.0
// Contour material: moving reflection v2.
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform vec2 uPointer;
uniform float uPower;
uniform float uFoilAspect;
uniform float uContourPower;
uniform float uFoilStrength;
uniform vec3 uCamera;
uniform float uDistance;
uniform vec4 uSourceRect;
uniform sampler2D uCard;
uniform sampler2D uFoil;
uniform sampler2D uContour;
uniform sampler2D uBloom;
uniform sampler2D uBackground;
uniform sampler2D uForeground;
out vec4 fragColor;
#include "foil_material.glsl"
#include "contour_material.glsl"
void main() {
  vec2 uv = FlutterFragCoord().xy / uSize;
  vec4 source = texture(uCard, uv);
  vec3 card = source.rgb / max(source.a, 0.001);
  // Camera and distance are in card-width units. Neutral projection is identity.
  vec2 ratio = vec2(1.0, uSize.y/uSize.x);
  vec2 p = (uv-0.5)*ratio;
  vec2 q = (p + uDistance/uCamera.z*(p-uCamera.xy))/(1.0+uDistance/2.0);
  vec2 backgroundUv = uSourceRect.xy + (q/ratio+0.5)*uSourceRect.zw;
  vec4 foreground = texture(uForeground, uv);
  vec3 background = texture(uBackground, backgroundUv).rgb;
  float owner = clamp(foreground.a/max(source.a, 0.001), 0.0, 1.0);
  // Apply only the background delta to the original composite. This preserves
  // exact neutral colors and avoids double-filtered fringes at matte boundaries.
  vec3 neutralBackground = texture(uBackground, uSourceRect.xy+uv*uSourceRect.zw).rgb;
  card = clamp(card + (background-neutralBackground)*(1.0-owner), 0.0, 1.0);
  // Soft occlusion belongs to the recessed plane, never to the foreground.
  // Its direction follows the projected separation; zero depth/neutral remain exact.
  vec2 separation = q / ratio + 0.5 - uv;
  vec2 shadowUv = uv - separation * 0.45;
  vec2 feather = vec2(0.0035, 0.0035 / ratio.y);
  float shadow = texture(uForeground, shadowUv).a * 0.40;
  shadow += texture(uForeground, shadowUv + vec2(feather.x, 0.0)).a * 0.15;
  shadow += texture(uForeground, shadowUv - vec2(feather.x, 0.0)).a * 0.15;
  shadow += texture(uForeground, shadowUv + vec2(0.0, feather.y)).a * 0.15;
  shadow += texture(uForeground, shadowUv - vec2(0.0, feather.y)).a * 0.15;
  float separationAmount = smoothstep(0.0, 0.035, length(separation));
  card *= 1.0 - shadow * (1.0 - owner) * separationAmount * 0.22 * uPower;
  vec3 result = foilMaterial(uv, card, uPower * uFoilStrength);
  result = contourMaterial(uv, card, result);
  fragColor = vec4(result*source.a, source.a);
}

// SPDX-License-Identifier: GPL-3.0
// Source-aligned reflection, shared by height and medium. Never offset the maps.
vec3 contourMaterial(vec2 uv, vec3 card, vec3 foil) {
  float line = texture(uContour, uv).r;
  vec2 bloom = texture(uBloom, uv).rg;
  // The same light coordinates as foilMaterial. Turning the card sweeps a
  // specular band across the printed edges; the edges themselves stay fixed.
  vec2 light = uPointer - 0.5;
  float position = dot(uv - 0.5, vec2(0.731354, 0.681998));
  float center = dot(light, vec2(0.95, -0.85));
  float distanceToBand = position - center;
  float coreReflection = exp(-pow(distanceToBand / 0.14, 2.0));
  float haloReflection = exp(-pow(distanceToBand / 0.25, 2.0));
  float strength = uContourPower * sqrt(clamp(uPower, 0.0, 1.0));
  float reflectedLine = line * coreReflection;
  // Recover headroom only beneath the moving glint. Do not darken the card
  // globally or leave a permanently illuminated outline.
  vec3 base = mix(foil, card, clamp(reflectedLine * strength * 0.65, 0.0, 1.0));
  float emission = min((reflectedLine * 1.35
      + bloom.r * coreReflection * 0.65
      + bloom.g * haloReflection * 0.30) * strength, 0.60);
  return clamp(base + vec3(emission), 0.0, 1.0);
}

// SPDX-License-Identifier: GPL-3.0
// Adapted from simeydotme/pokemon-cards-css; see licenses/.
float luminance(vec3 c) { return dot(c, vec3(0.3, 0.59, 0.11)); }
vec3 exclusion(vec3 a, vec3 b) { return a + b - 2.0 * a * b; }
vec3 hardLight(vec3 base, vec3 layer) {
  return mix(2.0 * base * layer, 1.0 - 2.0 * (1.0-base) * (1.0-layer), step(vec3(0.5), layer));
}
vec3 dodge(vec3 base, vec3 layer) { return min(vec3(1.0), base / max(vec3(0.001), 1.0-layer)); }

// 光谱保留自身饱和度，以斜向亮带提供明暗；越界颜色按亮度收缩，避免直接截断色相。
vec3 withLuminance(vec3 color, float lightness) {
  vec3 c = color + lightness - luminance(color);
  float lo = min(c.r, min(c.g, c.b));
  float hi = max(c.r, max(c.g, c.b));
  if (lo < 0.0) c = lightness + (c-lightness) * lightness / max(0.001, lightness-lo);
  if (hi > 1.0) c = lightness + (c-lightness) * (1.0-lightness) / max(0.001, hi-lightness);
  return c;
}

// 红、黄、绿、青、蓝、紫六个 sunpillar 色标，首尾连续循环。
vec3 spectrum(float position) {
  float p = fract(position) * 6.0;
  vec3 a = vec3(1.0, 0.478, 0.46);
  vec3 b = vec3(1.0, 0.928, 0.38);
  vec3 c = vec3(0.659, 1.0, 0.38);
  vec3 d = vec3(0.52, 1.0, 0.968);
  vec3 e = vec3(0.48, 0.584, 1.0);
  vec3 f = vec3(0.847, 0.46, 1.0);
  if (p < 1.0) return mix(a, b, p);
  if (p < 2.0) return mix(b, c, p-1.0);
  if (p < 3.0) return mix(c, d, p-2.0);
  if (p < 4.0) return mix(d, e, p-3.0);
  if (p < 5.0) return mix(e, f, p-4.0);
  return mix(f, a, p-5.0);
}

// CSS 133° 的投影方向；渐变周期为背景对角投影长度的 12%。
// 反向层连续延展亮带，避免跨过背景边界时整条反射突然跳变。
vec3 bands(vec2 uv, vec2 background, float widthScale) {
  vec2 scale = vec2(widthScale, 1.0);
  vec2 p = (uv - (1.0-scale) * background) / scale;
  vec2 direction = vec2(0.731354, 0.681998);
  vec2 physical = scale * vec2(uSize.x/uSize.y, 1.0);
  float t = 0.5 + dot((p-0.5)*physical, direction) / dot(physical, abs(direction));
  float phase = mod(t, 0.12);
  vec3 dark = vec3(0.055, 0.082, 0.18);
  vec3 middle = vec3(0.56, 0.64, 0.64);
  vec3 bright = vec3(0.561, 0.759, 0.759);
  if (phase < 0.038) return mix(dark, middle, phase/0.038);
  if (phase < 0.045) return mix(middle, bright, (phase-0.038)/0.007);
  if (phase < 0.052) return mix(bright, middle, (phase-0.045)/0.007);
  if (phase < 0.10) return mix(middle, dark, (phase-0.052)/0.048);
  return dark;
}

// 两层各自调整亮度、对比和饱和度，合成后保留交错光谱，不再重复压缩。
vec3 filtered(vec3 c, float brightness, float contrast, float saturation) {
  c = (c * brightness - 0.5) * contrast + 0.5;
  c = mix(vec3(luminance(c)), c, saturation);
  return clamp(c, 0.0, 1.0);
}

vec3 foilMaterial(vec2 uv, vec3 card, float power) {
  // 指针 0–100% 对应背景横向 37–63%、纵向 33–67%。
  vec2 background = vec2(0.37, 0.33) + uPointer * vec2(0.26, 0.34);
  float fromCenter = clamp(length((uPointer-0.5)*2.0), 0.0, 1.0);
  vec2 bandPosition = vec2(background.x + background.y*0.2, background.y);

  // 箔纹从卡面原点固定平铺；宽度为卡宽的 33%，保留纹理宽高比。
  vec2 tileSize = vec2(0.33, 0.33 * uSize.x / uSize.y / uFoilAspect);
  vec3 grain = texture(uFoil, fract(uv/tileSize)).rgb;
  float rainbowY = (uv.y + 6.0*background.y) / 7.0;
  vec3 rainbow = spectrum((-rainbowY-0.05)/0.30);
  vec3 shine = withLuminance(rainbow, luminance(bands(uv, bandPosition, 3.0)));
  shine = filtered(exclusion(shine, grain), 0.35 + fromCenter*0.3, 2.0, 1.5);

  // 第二层使用不同背景尺寸反向移动，exclusion 形成交错的彩色明暗条带。
  float reverseY = (uv.y + 3.0*background.y) / 4.0;
  vec3 reverse = withLuminance(spectrum((-reverseY-0.05)/0.30), luminance(bands(uv, -bandPosition, 1.95)));
  reverse = filtered(exclusion(reverse, grain), 0.8 + fromCenter*0.5, 1.6, 1.4);
  shine = exclusion(shine, reverse);

  // 箔层能量取 72%，保留白色印刷区域的层次，避免 color-dodge 过曝。
  vec3 result = mix(card, dodge(card, shine * 0.72), power);
  vec2 ratio = vec2(uSize.x/uSize.y, 1.0);
  float farCorner = length(max(uPointer, 1.0-uPointer)*ratio);
  float distanceToLight = length((uv-uPointer)*ratio) / max(farCorner, 0.001);
  vec3 glare = mix(vec3(0.75), vec3(0.333, 0.357, 0.368), clamp((distanceToLight-0.05)/0.55, 0.0, 1.0));
  glare = mix(glare, vec3(0.14, 0.06, 0.113), clamp((distanceToLight-0.6)/0.9, 0.0, 1.0));
  // 高光覆盖强度为箔光的 75%，与彩虹层共同形成明暗，不对整卡强行抬黑。
  result = mix(result, hardLight(result, filtered(glare, 1.0, 1.2, 1.0)), power*0.75);
  return clamp(result, 0.0, 1.0);
}

import 'dart:async';
import 'dart:math' as math;
import 'dart:ui' as ui;

import 'package:flutter/material.dart';

import 'holographic_card_painter.dart';

enum HolographicCardMode { height, medium, low }

/// Pose uses x right and y up, each in [-1, 1]. Internal depth is independent
/// of material sensitivity and optional physical rotation.
class HolographicCard extends StatefulWidget {
  const HolographicCard({
    required this.cardImage,
    required this.backgroundImage,
    required this.foregroundImage,
    this.depth = 1,
    this.backgroundMotionStrength = 1,
    this.backgroundSourceRect = const Rect.fromLTWH(
      8 / 116,
      8 / 116,
      100 / 116,
      100 / 116,
    ),
    required this.foregroundContourImage,
    required this.foregroundBloomImage,
    this.foilImage = const AssetImage(
      'assets/holographic_foil.png',
      package: 'build_flutter_holo_card_template',
    ),
    this.shaderAssetPath,
    this.effectStrength = 0.8,
    this.foilStrength = 1,
    this.contourGlowStrength = 0.55,
    this.idleEffectStrength = 0.22,
    this.viewSensitivity = 1,
    this.maxTiltRadians = 0.24,
    this.applyPhysicalTilt = true,
    this.autoPlay = false,
    this.controlledTilt,
    this.controlledActivation,
    this.onError,
    this.semanticLabel = 'Interactive holographic card',
    super.key,
  }) : mode = HolographicCardMode.height,
       assert(
         depth >= 0 && depth <= 3,
         'Negative depth is no longer supported; migrate to background distance 0–3.',
       ),
       assert(effectStrength >= 0 && effectStrength <= 1),
       assert(foilStrength >= 0 && foilStrength <= 1),
       assert(contourGlowStrength >= 0 && contourGlowStrength <= 1),
       assert(maxTiltRadians >= 0 && maxTiltRadians <= 0.35);

  const HolographicCard.height({
    required this.cardImage,
    required this.backgroundImage,
    required this.foregroundImage,
    this.depth = 1,
    this.backgroundMotionStrength = 1,
    this.backgroundSourceRect = const Rect.fromLTWH(
      8 / 116,
      8 / 116,
      100 / 116,
      100 / 116,
    ),
    required this.foregroundContourImage,
    required this.foregroundBloomImage,
    this.foilImage = const AssetImage(
      'assets/holographic_foil.png',
      package: 'build_flutter_holo_card_template',
    ),
    this.shaderAssetPath,
    this.effectStrength = 0.8,
    this.foilStrength = 1,
    this.contourGlowStrength = 0.55,
    this.idleEffectStrength = 0.22,
    this.viewSensitivity = 1,
    this.maxTiltRadians = 0.24,
    this.applyPhysicalTilt = true,
    this.autoPlay = false,
    this.controlledTilt,
    this.controlledActivation,
    this.onError,
    this.semanticLabel = 'Interactive holographic card',
    super.key,
  }) : mode = HolographicCardMode.height,
       assert(
         depth >= 0 && depth <= 3,
         'Negative depth is no longer supported; migrate to background distance 0–3.',
       ),
       assert(effectStrength >= 0 && effectStrength <= 1),
       assert(foilStrength >= 0 && foilStrength <= 1),
       assert(contourGlowStrength >= 0 && contourGlowStrength <= 1),
       assert(maxTiltRadians >= 0 && maxTiltRadians <= 0.35);

  const HolographicCard.medium({
    required this.cardImage,
    required this.foregroundContourImage,
    required this.foregroundBloomImage,
    this.foilImage = const AssetImage(
      'assets/holographic_foil.png',
      package: 'build_flutter_holo_card_template',
    ),
    this.shaderAssetPath,
    this.effectStrength = 0.8,
    this.foilStrength = 1,
    this.contourGlowStrength = 0.55,
    this.idleEffectStrength = 0.22,
    this.viewSensitivity = 1,
    this.maxTiltRadians = 0.24,
    this.applyPhysicalTilt = true,
    this.autoPlay = false,
    this.controlledTilt,
    this.controlledActivation,
    this.onError,
    this.semanticLabel = 'Interactive holographic card',
    super.key,
  }) : mode = HolographicCardMode.medium,
       backgroundImage = null,
       foregroundImage = null,
       depth = 0,
       backgroundMotionStrength = 0,
       backgroundSourceRect = const Rect.fromLTWH(0, 0, 1, 1),
       assert(effectStrength >= 0 && effectStrength <= 1),
       assert(foilStrength >= 0 && foilStrength <= 1),
       assert(contourGlowStrength >= 0 && contourGlowStrength <= 1),
       assert(maxTiltRadians >= 0 && maxTiltRadians <= 0.35);

  const HolographicCard.low({
    required this.cardImage,
    this.foilImage = const AssetImage(
      'assets/holographic_foil.png',
      package: 'build_flutter_holo_card_template',
    ),
    this.shaderAssetPath,
    this.effectStrength = 0.8,
    this.foilStrength = 1,
    this.contourGlowStrength = 0.55,
    this.idleEffectStrength = 0.22,
    this.viewSensitivity = 1,
    this.maxTiltRadians = 0.24,
    this.applyPhysicalTilt = true,
    this.autoPlay = false,
    this.controlledTilt,
    this.controlledActivation,
    this.onError,
    this.semanticLabel = 'Interactive holographic card',
    super.key,
  }) : mode = HolographicCardMode.low,
       backgroundImage = null,
       foregroundImage = null,
       depth = 0,
       backgroundMotionStrength = 0,
       backgroundSourceRect = const Rect.fromLTWH(0, 0, 1, 1),
       foregroundContourImage = null,
       foregroundBloomImage = null,
       assert(effectStrength >= 0 && effectStrength <= 1),
       assert(foilStrength >= 0 && foilStrength <= 1),
       assert(contourGlowStrength >= 0 && contourGlowStrength <= 1),
       assert(maxTiltRadians >= 0 && maxTiltRadians <= 0.35);

  final HolographicCardMode mode;
  final ImageProvider cardImage;
  final ImageProvider foilImage;
  final ImageProvider? backgroundImage, foregroundImage;
  final ImageProvider? foregroundContourImage, foregroundBloomImage;
  final String? shaderAssetPath;
  final Rect backgroundSourceRect;

  /// Foil-only intensity. Zero keeps contour light; effectStrength zero disables both.
  final double foilStrength;

  /// Multiplier for height background recession, capped to valid overscan.
  final double backgroundMotionStrength;
  final double depth, effectStrength, contourGlowStrength, idleEffectStrength;
  final double viewSensitivity, maxTiltRadians;
  final bool applyPhysicalTilt, autoPlay;
  final Offset? controlledTilt;
  final double? controlledActivation;
  final void Function(Object error, StackTrace stack)? onError;
  final String semanticLabel;

  @override
  State<HolographicCard> createState() => _HolographicCardState();
}

class _HolographicCardState extends State<HolographicCard>
    with TickerProviderStateMixin, WidgetsBindingObserver {
  late final AnimationController _returnController;
  late final AnimationController _autoController;
  bool _foreground = true;
  late final AnimationController _effectController;

  _Resources? _resources;
  final Set<void Function()> _cancelLoads = {};
  bool get _reduceMotion => MediaQuery.disableAnimationsOf(context);
  Offset _tilt = Offset.zero;
  Offset? _dragStartPosition;
  Offset? _dragStartTilt;
  int? _activePointer;
  bool _hovering = false;
  Animation<Offset>? _returnAnimation;
  double _effectActivation = 0;
  double _effectStartActivation = 0;
  double _effectTargetActivation = 0;
  Curve _effectCurve = Curves.linear;
  int _loadGeneration = 0;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _autoController =
        AnimationController(vsync: this, duration: const Duration(seconds: 8))
          ..addListener(() {
            if (mounted) setState(() {});
          });
    _returnController =
        AnimationController(
            vsync: this,
            duration: const Duration(milliseconds: 240),
          )
          ..addListener(_handleReturn)
          ..addStatusListener((status) {
            if (status == AnimationStatus.completed && mounted) _syncAutoPlay();
          });
    _effectController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 180),
    )..addListener(_handleEffectTransition);
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _syncAutoPlay();
    if (_loadGeneration == 0) {
      _startLoading();
    }
  }

  @override
  void didUpdateWidget(HolographicCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    _syncAutoPlay();
    if (oldWidget.backgroundSourceRect != widget.backgroundSourceRect ||
        oldWidget.mode != widget.mode ||
        oldWidget.foilImage != widget.foilImage ||
        oldWidget.cardImage != widget.cardImage ||
        oldWidget.backgroundImage != widget.backgroundImage ||
        oldWidget.foregroundImage != widget.foregroundImage ||
        oldWidget.foregroundContourImage != widget.foregroundContourImage ||
        oldWidget.foregroundBloomImage != widget.foregroundBloomImage ||
        oldWidget.shaderAssetPath != widget.shaderAssetPath) {
      _startLoading();
    }
  }

  void _syncAutoPlay() {
    final active =
        widget.autoPlay &&
        widget.controlledTilt == null &&
        !_hovering &&
        _activePointer == null &&
        !_returnController.isAnimating &&
        !_reduceMotion &&
        _foreground &&
        TickerMode.valuesOf(context).enabled;
    if (active) {
      if (!_autoController.isAnimating) _autoController.repeat();
    } else {
      _autoController.stop();
    }
    if (_reduceMotion || !_foreground) {
      _returnController.stop();
      _effectController.stop();
      _tilt = Offset.zero;
      _effectActivation = 0;
      _returnAnimation = null;
      if (!_foreground) {
        _activePointer = null;
        _hovering = false;
        _dragStartPosition = null;
        _dragStartTilt = null;
      }
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    _foreground = state == AppLifecycleState.resumed;
    _syncAutoPlay();
    if (mounted) setState(() {});
  }

  void _startLoading() {
    final int generation = ++_loadGeneration;
    for (final cancel in _cancelLoads.toList()) {
      cancel();
    }
    _resources?.dispose();
    _resources = null;
    final ImageConfiguration configuration = createLocalImageConfiguration(
      context,
    );
    unawaited(
      _loadResources(configuration).then(
        (resources) {
          if (!mounted || generation != _loadGeneration) {
            resources.dispose();
            return;
          }
          setState(() => _resources = resources);
        },
        onError: (Object error, StackTrace stackTrace) {
          if (!mounted || generation != _loadGeneration) {
            return;
          }
          if (widget.onError != null) {
            widget.onError!(error, stackTrace);
            return;
          }
          FlutterError.reportError(
            FlutterErrorDetails(
              exception: error,
              stack: stackTrace,
              library: 'holographic card',
            ),
          );
        },
      ),
    );
  }

  Future<_Resources> _loadResources(ImageConfiguration configuration) async {
    final config = widget;
    final generation = _loadGeneration;
    final List<ui.Image> loadedImages = [];
    try {
      Future<ui.Image> load(ImageProvider provider) async {
        final ui.Image image = await _loadImage(provider, configuration);
        loadedImages.add(image);
        if (!mounted || generation != _loadGeneration)
          throw StateError('Superseded load');
        return image;
      }

      final ui.Image cardMaskImage = await load(config.cardImage);
      if (config.depth < 0 || config.depth > 3) {
        throw ArgumentError(
          'Migrate depth to background distance 0–3; negative depth was removed.',
        );
      }
      final foil = await load(config.foilImage);
      final images = <ui.Image>[cardMaskImage, foil];
      if (config.mode != HolographicCardMode.low) {
        images.add(await load(config.foregroundContourImage!));
        images.add(await load(config.foregroundBloomImage!));
      }
      if (config.mode == HolographicCardMode.height) {
        images.add(await load(config.backgroundImage!));
        images.add(await load(config.foregroundImage!));
        final rect = config.backgroundSourceRect;
        final bg = images[4];
        if ((rect.width * bg.width - cardMaskImage.width).abs() > 1.5 ||
            (rect.height * bg.height - cardMaskImage.height).abs() > 1.5 ||
            rect.left < 0.06 ||
            rect.top < 0.06 ||
            rect.right > 0.94 ||
            rect.bottom > 0.94) {
          throw ArgumentError(
            'height requires an extended background and its source rectangle (8% per side).',
          );
        }
      }
      for (var i = 2; i < images.length; i++) {
        if (i == 4) continue;
        if (images[i].width != cardMaskImage.width ||
            images[i].height != cardMaskImage.height) {
          throw ArgumentError(
            'Card, foreground, contour and bloom must share the exact source canvas.',
          );
        }
      }
      final name = config.mode == HolographicCardMode.height
          ? 'holographic_card'
          : config.mode.name;
      final program = await ui.FragmentProgram.fromAsset(
        config.shaderAssetPath ??
            'packages/build_flutter_holo_card_template/shaders/$name.frag',
      );
      return _Resources(images, program.fragmentShader());
    } catch (_) {
      for (final ui.Image image in loadedImages) {
        image.dispose();
      }
      rethrow;
    }
  }

  Future<ui.Image> _loadImage(
    ImageProvider provider,
    ImageConfiguration configuration,
  ) {
    final Completer<ui.Image> completer = Completer<ui.Image>();
    final ImageStream stream = provider.resolve(configuration);
    late final ImageStreamListener listener;
    late final void Function() cancel;
    cancel = () {
      stream.removeListener(listener);
      _cancelLoads.remove(cancel);
      if (!completer.isCompleted)
        completer.completeError(
          StateError('Image load superseded or disposed'),
        );
    };
    listener = ImageStreamListener(
      (ImageInfo info, bool synchronousCall) {
        stream.removeListener(listener);
        _cancelLoads.remove(cancel);
        if (!completer.isCompleted) completer.complete(info.image.clone());
        info.dispose();
      },
      onError: (Object error, StackTrace? stackTrace) {
        stream.removeListener(listener);
        _cancelLoads.remove(cancel);
        if (!completer.isCompleted) completer.completeError(error, stackTrace);
      },
    );
    _cancelLoads.add(cancel);
    stream.addListener(listener);
    return completer.future;
  }

  void _updateHover(Offset localPosition, Size size) {
    if (size.isEmpty || _activePointer != null) {
      return;
    }
    _returnController.stop();
    _returnAnimation = null;
    final Offset next = Offset(
      (localPosition.dx / size.width * 2 - 1).clamp(-1.0, 1.0),
      -(localPosition.dy / size.height * 2 - 1).clamp(-1.0, 1.0),
    );
    if (next != _tilt) {
      setState(() => _tilt = next);
    }
  }

  void _stopAutoForInteraction() {
    if (_autoController.isAnimating) {
      if (_tilt.distance < .001) {
        final phase = _autoController.value * math.pi * 2;
        _tilt = Offset(math.sin(phase) * .55, math.sin(phase * 2) * .35);
      }
      _autoController.stop();
      _autoController.value = 0;
    }
  }

  void _beginDrag(int pointer, Offset localPosition, Size size) {
    if (size.isEmpty || _activePointer != null) {
      return;
    }
    _stopAutoForInteraction();
    _returnController.stop();
    _returnAnimation = null;
    _activePointer = pointer;
    _dragStartPosition = localPosition;
    _dragStartTilt = _tilt;
    _activateEffect();
  }

  void _updateDrag(Offset localPosition, Size size) {
    if (size.isEmpty || _activePointer == null) {
      return;
    }
    final Offset startPosition = _dragStartPosition ?? localPosition;
    final Offset startTilt = _dragStartTilt ?? _tilt;
    final Offset next = Offset(
      (startTilt.dx + (localPosition.dx - startPosition.dx) / size.width * 2)
          .clamp(-1.0, 1.0),
      (startTilt.dy + (startPosition.dy - localPosition.dy) / size.height * 2)
          .clamp(-1.0, 1.0),
    );
    if (next != _tilt) {
      setState(() => _tilt = next);
    }
  }

  void _endDrag(int pointer) {
    if (_activePointer != pointer) {
      return;
    }
    _activePointer = null;
    _dragStartPosition = null;
    _dragStartTilt = null;
    _resetTilt();
    if (!_hovering) {
      _deactivateEffect();
    }
    _syncAutoPlay();
  }

  void _resetTilt() {
    if (_reduceMotion) {
      setState(() => _tilt = Offset.zero);
      return;
    }
    if (_tilt == Offset.zero) {
      return;
    }
    _returnAnimation = Tween<Offset>(begin: _tilt, end: Offset.zero).animate(
      CurvedAnimation(parent: _returnController, curve: Curves.easeOutCubic),
    );
    _returnController.forward(from: 0);
  }

  void _handleReturn() {
    final Animation<Offset>? animation = _returnAnimation;
    if (animation != null) {
      setState(() => _tilt = animation.value);
    }
  }

  void _activateEffect() {
    _startEffectTransition(
      targetActivation: 1,
      duration: const Duration(milliseconds: 180),
      curve: Curves.easeOutCubic,
    );
  }

  void _deactivateEffect() {
    _startEffectTransition(
      targetActivation: 0,
      duration: const Duration(milliseconds: 260),
      curve: Curves.easeOutCubic,
    );
  }

  void _startEffectTransition({
    required double targetActivation,
    required Duration duration,
    required Curve curve,
  }) {
    if (_reduceMotion) {
      setState(() => _effectActivation = targetActivation);
      return;
    }
    if (_effectTargetActivation == targetActivation &&
        (_effectController.isAnimating ||
            _effectActivation == targetActivation)) {
      return;
    }
    _effectController
      ..stop()
      ..duration = duration;
    _effectStartActivation = _effectActivation;
    _effectTargetActivation = targetActivation;
    _effectCurve = curve;
    _effectController.forward(from: 0);
  }

  void _handleEffectTransition() {
    final double progress = _effectCurve.transform(_effectController.value);
    setState(() {
      _effectActivation = ui.lerpDouble(
        _effectStartActivation,
        _effectTargetActivation,
        progress,
      )!;
    });
  }

  @override
  void dispose() {
    _loadGeneration++;
    for (final cancel in _cancelLoads.toList()) {
      cancel();
    }
    _resources?.dispose();
    WidgetsBinding.instance.removeObserver(this);
    _autoController.dispose();
    _returnController.dispose();
    _effectController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.backgroundMotionStrength.isFinite ||
        widget.backgroundMotionStrength < 0 ||
        widget.backgroundMotionStrength > 4) {
      throw ArgumentError(
        'backgroundMotionStrength must be finite and within 0–4.',
      );
    }
    if (!widget.depth.isFinite || widget.depth < 0 || widget.depth > 3) {
      throw ArgumentError(
        'Negative depth removed: migrate to background distance 0–3.',
      );
    }
    if (!widget.maxTiltRadians.isFinite ||
        widget.maxTiltRadians < 0 ||
        widget.maxTiltRadians > .35) {
      throw ArgumentError(
        'maxTiltRadians must be between 0 and 0.35 for overscan safety.',
      );
    }
    final _Resources? resources = _resources;
    if (resources == null) {
      return Semantics(
        image: true,
        label: widget.semanticLabel,
        child: Image(
          image: widget.cardImage,
          fit: BoxFit.contain,
          filterQuality: FilterQuality.high,
        ),
      );
    }

    final double aspectRatio =
        resources.cardMaskImage.width / resources.cardMaskImage.height;
    return LayoutBuilder(
      builder: (BuildContext context, BoxConstraints constraints) {
        final bool boundedWidth = constraints.hasBoundedWidth;
        final bool boundedHeight = constraints.hasBoundedHeight;
        if (boundedWidth && boundedHeight) {
          final double maxWidth = constraints.maxWidth;
          final double maxHeight = constraints.maxHeight;
          final double width = math.min(maxWidth, maxHeight * aspectRatio);
          final double height = width / aspectRatio;
          return Align(
            alignment: Alignment.center,
            child: SizedBox(
              width: width,
              height: height,
              child: _buildCard(resources, Size(width, height)),
            ),
          );
        }
        if (boundedWidth) {
          final double width = constraints.maxWidth;
          final double height = width / aspectRatio;
          return SizedBox(
            width: width,
            height: height,
            child: _buildCard(resources, Size(width, height)),
          );
        }
        if (boundedHeight) {
          final double height = constraints.maxHeight;
          final double width = height * aspectRatio;
          return SizedBox(
            width: width,
            height: height,
            child: _buildCard(resources, Size(width, height)),
          );
        }
        final double width = math.min(
          320,
          resources.cardMaskImage.width.toDouble(),
        );
        final double height = width / aspectRatio;
        return SizedBox(
          width: width,
          height: height,
          child: _buildCard(resources, Size(width, height)),
        );
      },
    );
  }

  Widget _buildCard(_Resources resources, Size size) {
    final phase = _autoController.value * math.pi * 2;
    final automatic =
        widget.autoPlay &&
        !_reduceMotion &&
        !_hovering &&
        _activePointer == null &&
        _tilt.distance < .001;
    final autoPose = Offset(math.sin(phase) * .55, math.sin(phase * 2) * .35);
    final rawPose = widget.controlledTilt ?? (automatic ? autoPose : _tilt);
    final pose = Offset(
      rawPose.dx.clamp(-1.0, 1.0),
      rawPose.dy.clamp(-1.0, 1.0),
    );
    final physical = widget.applyPhysicalTilt && !_reduceMotion;
    final perspective = Matrix4.identity()
      ..setEntry(3, 2, -1 / (size.width * 2));
    if (physical) {
      perspective.rotateX(pose.dy * widget.maxTiltRadians);
      perspective.rotateY(pose.dx * widget.maxTiltRadians);
    }

    return Semantics(
      image: true,
      label: widget.semanticLabel,
      child: MouseRegion(
        onEnter: (_) {
          _hovering = true;
          _stopAutoForInteraction();
          _activateEffect();
        },
        onHover: (event) => _updateHover(event.localPosition, size),
        onExit: (_) {
          _hovering = false;
          if (_activePointer == null) {
            _resetTilt();
            _deactivateEffect();
          }
          _syncAutoPlay();
        },
        child: Listener(
          behavior: HitTestBehavior.opaque,
          onPointerDown: (event) =>
              _beginDrag(event.pointer, event.localPosition, size),
          onPointerUp: (event) => _endDrag(event.pointer),
          onPointerCancel: (event) => _endDrag(event.pointer),
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onPanUpdate: (details) => _updateDrag(details.localPosition, size),
            child: Transform(
              key: const ValueKey('holographic-card-transform'),
              alignment: Alignment.center,
              transform: perspective,
              child: RepaintBoundary(
                key: const ValueKey('holographic-card-renderer'),
                child: CustomPaint(
                  painter: _createPainter(resources, pose),
                  child: const SizedBox.expand(),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  HolographicCardPainter _createPainter(
    _Resources resources,
    Offset shaderView,
  ) {
    // An autoplay presentation is active even without hover/touch. Keep the
    // full material while interaction takes over; explicit activation wins.
    final presenting =
        widget.autoPlay &&
        !_reduceMotion &&
        _foreground &&
        TickerMode.valuesOf(context).enabled;
    final activation =
        (widget.controlledActivation ?? (presenting ? 1.0 : _effectActivation))
            .clamp(0.0, 1.0);
    return HolographicCardPainter(
      shader: resources.shader,
      images: resources.images,
      mode: widget.mode.name,
      view: shaderView,
      maxTiltRadians: widget.maxTiltRadians,
      viewSensitivity: widget.viewSensitivity,
      depth: _reduceMotion ? 0 : widget.depth,
      sourceRect: widget.backgroundSourceRect,
      backgroundMotionStrength: widget.backgroundMotionStrength,
      effectStrength:
          widget.effectStrength *
          ui.lerpDouble(widget.idleEffectStrength, 1, activation)!,
      contourGlowStrength: widget.contourGlowStrength,
      foilStrength: widget.foilStrength,
    );
  }
}

class _Resources {
  _Resources(this.images, this.shader);
  final List<ui.Image> images;
  ui.Image get cardMaskImage => images.first;
  final ui.FragmentShader shader;
  void dispose() {
    for (final image in images) {
      image.dispose();
    }
    shader.dispose();
  }
}

import 'dart:math' as math;
import 'dart:ui' as ui;
import 'package:flutter/material.dart';

/// Inverse of rotateX(pitch) * rotateY(yaw), with camera at (0, 0, 2).
List<double> backgroundCamera(Offset view, double radians) {
  final pitch = view.dy * radians, yaw = view.dx * radians;
  return [
    -2 * math.sin(yaw) * math.cos(pitch),
    2 * math.sin(pitch),
    2 * math.cos(yaw) * math.cos(pitch),
  ];
}

Offset projectBackgroundUv(
  Offset uv,
  double aspect,
  Offset pose,
  double radians,
  double depth,
) {
  final c = backgroundCamera(pose, radians);
  final d = 0.04 * math.min(1.0, 1 / aspect) * depth;
  final p = Offset(uv.dx - .5, (uv.dy - .5) / aspect);
  return Offset(
    (p.dx + d / c[2] * (p.dx - c[0])) / (1 + d / 2) + .5,
    (p.dy + d / c[2] * (p.dy - c[1])) / (1 + d / 2) * aspect + .5,
  );
}

// A single distance cap keeps the projection coherent; never clamp individual
// texture coordinates (which stretches/repeats the background at its edges).
double safeBackgroundDistance(
  double aspect,
  Offset pose,
  double radians,
  double depth,
  double strength,
  Rect sourceRect,
) {
  final camera = backgroundCamera(pose, radians);
  final requested = .04 * math.min(1.0, 1 / aspect) * depth * strength;
  bool fits(double d) {
    for (final x in [0.0, 1.0]) {
      for (final y in [0.0, 1.0]) {
        final px = x - .5, py = (y - .5) / aspect;
        final u = (px + d / camera[2] * (px - camera[0])) / (1 + d / 2) + .5;
        final v =
            (py + d / camera[2] * (py - camera[1])) / (1 + d / 2) * aspect + .5;
        final tx = sourceRect.left + u * sourceRect.width;
        final ty = sourceRect.top + v * sourceRect.height;
        if (tx < .002 || tx > .998 || ty < .002 || ty > .998) return false;
      }
    }
    return true;
  }

  if (fits(requested)) return requested;
  double lo = 0, hi = requested;
  for (var i = 0; i < 24; i++) {
    final mid = (lo + hi) / 2;
    if (fits(mid)) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  return lo;
}

class HolographicCardPainter extends CustomPainter {
  const HolographicCardPainter({
    required this.shader,
    required this.images,
    required this.mode,
    required this.view,
    required this.depth,
    this.backgroundMotionStrength = 1,
    required this.effectStrength,
    this.foilStrength = 1,
    required this.contourGlowStrength,
    required this.maxTiltRadians,
    required this.viewSensitivity,
    required this.sourceRect,
  });
  final ui.FragmentShader shader;
  final List<ui.Image> images;
  final String mode;
  final Offset view;
  final double backgroundMotionStrength;
  final double depth,
      effectStrength,
      foilStrength,
      contourGlowStrength,
      maxTiltRadians,
      viewSensitivity;
  final Rect sourceRect;

  @override
  void paint(Canvas canvas, Size size) {
    if (size.isEmpty) return;
    final values = <double>[
      size.width,
      size.height,
      (0.5 + view.dx * 0.5 * viewSensitivity).clamp(0, 1),
      (0.5 - view.dy * 0.5 * viewSensitivity).clamp(0, 1),
      mode == 'low' ? effectStrength * foilStrength : effectStrength,
      images[1].width / images[1].height,
    ];
    if (mode != 'low') values.addAll([contourGlowStrength, foilStrength]);
    if (mode == 'height') {
      values.addAll(backgroundCamera(view, maxTiltRadians));
      values.add(
        safeBackgroundDistance(
          size.width / size.height,
          view,
          maxTiltRadians,
          depth,
          backgroundMotionStrength,
          sourceRect,
        ),
      );
      values.addAll([
        sourceRect.left,
        sourceRect.top,
        sourceRect.width,
        sourceRect.height,
      ]);
    }
    for (var i = 0; i < values.length; i++) {
      shader.setFloat(i, values[i]);
    }
    for (var i = 0; i < images.length; i++) {
      shader.setImageSampler(i, images[i], filterQuality: FilterQuality.medium);
    }
    canvas.drawRect(Offset.zero & size, Paint()..shader = shader);
  }

  @override
  bool shouldRepaint(HolographicCardPainter old) =>
      old.shader != shader ||
      old.view != view ||
      old.depth != depth ||
      old.backgroundMotionStrength != backgroundMotionStrength ||
      old.effectStrength != effectStrength ||
      old.foilStrength != foilStrength ||
      old.contourGlowStrength != contourGlowStrength ||
      old.sourceRect != sourceRect ||
      old.maxTiltRadians != maxTiltRadians ||
      old.viewSensitivity != viewSensitivity;
}

