const initialSettings = {"mode": "height", "effect": 0.8, "foil": 1.0, "contour": 0.55, "depth": 2.0, "motion": 3.0, "sensitivity": 1.0, "tilt": 0.2, "auto": true, "physical": true, "poseX": null, "poseY": null};
const demoCard = {"title": "凯尔 · 正义天秤", "width": 1000, "height": 1389, "sourceRect": [0.06896551724137931, 0.069435833849969, 0.8620689655172413, 0.861128332300062]};
const availableModes = ["height", "medium", "low"];
